use std::{fs,path::{Path,PathBuf},collections::{BTreeMap,BTreeSet}};use serde_json::{Value,json};use sha2::{Digest,Sha256};
const R:&str="/tmp/zopro-poseidon-frontier";const TOOL:&str="/tmp/zopro-xtask-fast-screen-target/release/xtask";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn add(p:impl AsRef<Path>,pins:&mut BTreeMap<String,String>){let p=p.as_ref();pins.insert(p.display().to_string(),hash(p));}
fn prior()->BTreeSet<String>{let mut seen:BTreeSet<String>=serde_json::from_value(read("/tmp/zopro-g2-tree-sdk/context/manifest.json")["prior_proof_sha256"].clone()).unwrap();assert_eq!(seen.len(),5958);for p in ["/tmp/zopro-g2-tree-sdk/proof-inventory.json","/tmp/zopro-g1-quarter-current/proof-inventory.json","/tmp/zopro-pairing-x-chain-sdk/proof-inventory.json","/tmp/zopro-control-rescheduling/all-proof-inventory.json","/tmp/zopro-pairing-clean/proof-inventory.json","/tmp/zopro-borrowed-pending/proof-inventory.json","/tmp/zopro-borrowed-g1/proof-inventory.json"]{for(file,h)in read(p).as_object().unwrap(){assert_eq!(hash(file),h.as_str().unwrap());if file.ends_with(".proof"){assert!(seen.insert(h.as_str().unwrap().into()));}}}assert_eq!(seen.len(),6928);seen}
fn setup(){let r=Path::new(R);let m=read("/tmp/zopro-grouping-module/production-source-manifest.json");let mut pins=BTreeMap::new();let mut changed=Vec::new();
 for(p,h)in m["source_files_sha256"].as_object().unwrap(){let original=Path::new("/home/ubuntu/src/zk-tools/zopro").join(p);assert_eq!(hash(&original),h.as_str().unwrap());let candidate=r.join("candidate").join(p);if hash(&candidate)!=h.as_str().unwrap(){changed.push(p.clone());let old=fs::read_to_string(&original).unwrap();let new=fs::read_to_string(&candidate).unwrap();let recovered=new.replace("#[cfg(zopro_poseidon_census)] pub(super) mod census;\n","").replace("        #[cfg(zopro_poseidon_census)] sparse_poseidon::census::emit(self,&schedule);\n","");assert_eq!(old,recovered);}add(candidate,&mut pins);}
 assert_eq!(changed,vec!["crates/zopro-core/src/solver.rs","crates/zopro-core/src/solver/sparse_poseidon.rs"]);
 for rel in ["candidate/crates/zopro-core/src/solver/sparse_poseidon/census.rs","candidate/crates/zopro-bench/examples/cpu-sdk.rs","candidate/crates/zopro-bench/examples/support/perf.rs","experiment.rs","design.md"]{add(r.join(rel),&mut pins);}
 save(r.join("source-pins.json"),&json!(pins));save(r.join("source-audit.json"),&json!({"original_files":170,"originals_unchanged":168,"changed":changed,"all_original_source_bytes_recovered_after_removing_diagnostic_tokens":true,"new_module":"solver/sparse_poseidon/census.rs","arithmetic_changes":false,"execution_decision_changes":false,"new_execution_plan_or_lookup_table":false,"production_changed":false}));
 let text=serde_json::to_string(&read("/tmp/zopro-borrowed-pending/native-plan.json")).unwrap().replace("/tmp/zopro-borrowed-pending",R).replace("--cfg zopro_g2_prefix_records","--cfg zopro_g2_prefix_records --cfg zopro_poseidon_census");let mut plan:Value=serde_json::from_str(&text).unwrap();plan["environment"].as_object_mut().unwrap().remove("ZOPRO_CPU_BORROWED_PENDING");
 let steps=plan["steps"].as_array_mut().unwrap();steps.retain(|s|!["field","portable-consumers-field","no-ifma-consumers-field"].contains(&s["name"].as_str().unwrap()));
 for step in steps{if step["name"]=="core"{step["required_tests"]=json!([
 "solver::sparse_poseidon::census::tests::encoding_guard_and_malformed_spans",
 "solver::sparse_poseidon::census::tests::one_chain_does_not_supply_independent_lanes",
 "solver::sparse_poseidon::census::tests::mixed_widths_and_chain_tails",
 "solver::sparse_poseidon::census::tests::refined_container_is_excluded_and_waves_stay_separate"]);}}
 save(r.join("native-plan.json"),&plan);println!("Pinned pure schedule census; native core/raw/cubic and compatibility plan ready; field qualification inherited unchanged");
}
fn prepare(){let r=Path::new(R);assert_eq!(read(r.join("native/result.json"))["status"],"complete");assert_eq!(read(r.join("native/core/tests.json"))["passed_tests"].as_array().unwrap().len(),113);
 let mut pins:BTreeMap<String,String>=serde_json::from_value(read(r.join("source-pins.json"))).unwrap();let a=read(r.join("native/on/artifacts.json"));add(r.join("native/on/artifacts.json"),&mut pins);for(p,h)in a["input_pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());add(p,&mut pins);}add(a["binary"].as_str().unwrap(),&mut pins);assert_eq!(hash(a["binary"].as_str().unwrap()),a["binary_sha256"].as_str().unwrap());
 for p in [r.join("experiment"),r.join("native-plan.json"),r.join("native/result.json"),r.join("source-audit.json"),PathBuf::from(TOOL),PathBuf::from("/tmp/zopro-gnark-verify/verify"),PathBuf::from("/home/ubuntu/src/zk-tools/zopro/tools/zolana/zopro-keys.lock")]{add(p,&mut pins);}
 let p=read("/tmp/zopro-pairing-x-chain-sdk/perf-plan.json");let mut steps=Vec::new();let mut jobs=Vec::new();let previous=prior();save(r.join("prior-proofs.json"),&json!(previous));add(r.join("prior-proofs.json"),&mut pins);
 for case in p["cases"].as_array().unwrap().iter().filter(|c|c["workers"]==32){for workers in [16,32]{let name=format!("{}-w{workers}",case["shape"].as_str().unwrap());let stem=Path::new(case["image"].as_str().unwrap()).file_stem().unwrap();let out=r.join("proofs").join(&name).join(stem);let mut env=p["environment"].clone();env["RAYON_NUM_THREADS"]=json!(workers.to_string());env["ZOPRO_CPU_POSEIDON_FRONTIER"]=json!("1");env["ZOPRO_CPU_POSEIDON_TRACE"]=json!("1");let cpus=if workers==16{"0-15"}else{"0-31"};
  for key in ["image","request"]{add(case[key].as_str().unwrap(),&mut pins);}
  steps.push(json!({"kind":"command","name":name,"argv":["taskset","-c",cpus,a["binary"],case["image"],case["request"],"1",out],"environment":env,"timeout_seconds":600}));steps.push(json!({"kind":"command","name":format!("verify-{name}"),"argv":["/tmp/zopro-gnark-verify/verify","/tmp/zopro-keys",out.parent().unwrap(),"/home/ubuntu/src/zk-tools/zopro/tools/zolana/zopro-keys.lock"],"timeout_seconds":120}));jobs.push(json!({"name":name,"workers":workers,"shape":case["shape"],"directory":out,"public_sha256":case["public_sha256"]}));
 }}assert_eq!(jobs.len(),18);save(r.join("capture-jobs.json"),&json!(jobs));add(r.join("capture-jobs.json"),&mut pins);save(r.join("capture-pins.json"),&json!(pins));save(r.join("capture-plan.json"),&json!({"version":1,"source_pins":r.join("capture-pins.json"),"steps":steps}));println!("All9x16/32 structural census ready;72SDK18Gnark;prior6928");
}
fn main(){match std::env::args().nth(1).as_deref(){Some("setup")=>setup(),Some("prepare")=>prepare(),_=>panic!("mode")}}
